void Answer (int x, int pos) {
	ll C = Cnt;
	ll X = Sum;
	int K = (1ll << ptr[x]);
	for (int mask = 1; mask < K; mask++) {
		ll k = 1;
		for (int j = 0; j < ptr[x]; j++) {
			if ((mask >> j) & 1) {
				k *= d[x][j];
			}
		}
		int bits = __builtin_popcount(mask);
		int D = k;
		if (bits % 2 == 1) {
			C -= cnt[D];
			X -= s[D];
		} else {
			C += cnt[D];
			X += s[D];
		}
	}
	Ans += C * pos - X;
}

